INSERT INTO tasks (id, course_id, owner, title, description, published, task_type,
                   templates, tests, cpu_seconds, memory_kb, options, correct_option_ids) VALUES
    ('3b7da190-1763-5a10-b239-33ffda8b5855', 'e5682469-845e-5c93-aab0-bd09692f15a7', 'kodr-catalog', 'Приветствие на Rust', 'Считайте одну строку с именем. Выведите «Привет, <имя>!». Удалите перевод строки, сохранив пробелы внутри имени.', TRUE, 'PRACTICAL',
     $json$ {"RUST": "use std::io;\n\nfn main() {\n    let mut name = String::new();\n    io::stdin().read_line(&mut name).unwrap();\n    // Выведите приветствие.\n}\n"}$json$::jsonb, $json$ [{"stdin": "Ира\n", "expectedOutput": "Привет, Ира!"}, {"stdin": "Ada Lovelace\n", "expectedOutput": "Привет, Ada Lovelace!"}]$json$::jsonb, 2.0, 128000, NULL, NULL),
    ('d4f29fd5-89b9-5398-9c7e-ff7411c14cd7', 'e5682469-845e-5c93-aab0-bd09692f15a7', 'kodr-catalog', 'Компилятор Rust', 'Какая команда компилирует отдельный файл main.rs в исполняемую программу?', TRUE, 'QUIZ',
     NULL, NULL, NULL, NULL, $json$ [{"id": "a", "text": "rustc main.rs"}, {"id": "b", "text": "cargo new main.rs"}, {"id": "c", "text": "rustup show"}, {"id": "d", "text": "rustfmt main.rs"}]$json$::jsonb, $json$ ["a"]$json$::jsonb),
    ('d09a590e-01f3-5573-a838-74bf6ed6e78f', 'e5682469-845e-5c93-aab0-bd09692f15a7', 'kodr-catalog', 'Сумма чётных чисел', 'Считайте n (1 ≤ n ≤ 1000) и n целых чисел от −1000000 до 1000000. Напишите функцию is_even и выведите сумму чётных чисел. Если чётных чисел нет, выведите 0.', TRUE, 'PRACTICAL',
     $json$ {"RUST": "use std::io::{self, Read};\n\nfn is_even(_n: i32) -> bool {\n    false\n}\n\nfn main() {\n    let mut input = String::new();\n    io::stdin().read_to_string(&mut input).unwrap();\n    let mut numbers = input.split_whitespace();\n    let count: usize = numbers.next().unwrap().parse().unwrap();\n    // Просуммируйте чётные числа и выведите результат.\n}\n"}$json$::jsonb, $json$ [{"stdin": "6\n1 2 3 4 -6 5\n", "expectedOutput": "0"}, {"stdin": "4\n8 -3 10 1\n", "expectedOutput": "18"}, {"stdin": "3\n1 -3 5\n", "expectedOutput": "0"}, {"stdin": "1\n-2\n", "expectedOutput": "-2"}]$json$::jsonb, 2.0, 128000, NULL, NULL),
    ('56c3ec56-5217-5991-aae0-4bef3d776ef0', 'e5682469-845e-5c93-aab0-bd09692f15a7', 'kodr-catalog', 'Ветвления и циклы', 'Выберите все верные утверждения о конструкциях Rust.', TRUE, 'QUIZ',
     NULL, NULL, NULL, NULL, $json$ [{"id": "a", "text": "Условие if имеет тип bool."}, {"id": "b", "text": "match обязан обработать все варианты."}, {"id": "c", "text": "continue завершает весь цикл."}, {"id": "d", "text": "Диапазон 0..3 включает 3."}]$json$::jsonb, $json$ ["a", "b"]$json$::jsonb),
    ('6fe60e4c-2177-5c29-95ec-b1bfd2d3871d', 'e5682469-845e-5c93-aab0-bd09692f15a7', 'kodr-catalog', 'Сигнал светофора', 'Считайте одну строку: red, yellow или green. Представьте сигнал вариантом enum и через match выведите STOP, WAIT или GO соответственно.', TRUE, 'PRACTICAL',
     $json$ {"RUST": "use std::io;\n\nenum Signal {\n    Red,\n    Yellow,\n    Green,\n}\n\nfn main() {\n    let mut input = String::new();\n    io::stdin().read_line(&mut input).unwrap();\n    // Выберите Signal по входной строке и выведите команду.\n}\n"}$json$::jsonb, $json$ [{"stdin": "red\n", "expectedOutput": "STOP"}, {"stdin": "yellow\n", "expectedOutput": "WAIT"}, {"stdin": "green\n", "expectedOutput": "GO"}]$json$::jsonb, 2.0, 128000, NULL, NULL),
    ('511005a4-f308-5d06-a29b-dcc050676453', 'e5682469-845e-5c93-aab0-bd09692f15a7', 'kodr-catalog', 'Массивы и варианты enum', 'Какие утверждения верны? Выберите все правильные варианты.', TRUE, 'QUIZ',
     NULL, NULL, NULL, NULL, $json$ [{"id": "a", "text": "Элементы массива имеют один тип."}, {"id": "b", "text": "Все варианты enum обязаны хранить одинаковые данные."}, {"id": "c", "text": "Размер входит в тип массива."}, {"id": "d", "text": "if let извлекает данные из подходящего варианта."}]$json$::jsonb, $json$ ["a", "c", "d"]$json$::jsonb),
    ('f66cfb87-b9f6-5589-b3bd-335f06bc4709', 'e5682469-845e-5c93-aab0-bd09692f15a7', 'kodr-catalog', 'Строковый суффикс', 'Считайте две непустые строки и соедините их через «-». Реализуйте функцию append_suffix с параметрами &mut String и &str, затем напечатайте первую строку с добавленным суффиксом.', TRUE, 'PRACTICAL',
     $json$ {"RUST": "use std::io;\n\nfn append_suffix(_text: &mut String, _suffix: &str) {\n    // Добавьте дефис и суффикс к существующей строке.\n}\n\nfn main() {\n    let mut text = String::new();\n    let mut suffix = String::new();\n    io::stdin().read_line(&mut text).unwrap();\n    io::stdin().read_line(&mut suffix).unwrap();\n    let mut result = text.trim_end_matches(&['\\r', '\\n'][..]).to_owned();\n    let suffix = suffix.trim_end_matches(&['\\r', '\\n'][..]);\n    append_suffix(&mut result, suffix);\n    println!(\"{}\", result);\n}\n"}$json$::jsonb, $json$ [{"stdin": "kodr\nrust\n", "expectedOutput": "kodr-rust"}, {"stdin": "Имя\n01\n", "expectedOutput": "Имя-01"}, {"stdin": "hello world\nbeta build\n", "expectedOutput": "hello world-beta build"}]$json$::jsonb, 2.0, 128000, NULL, NULL),
    ('f30b175d-437e-55f9-9af0-ad7509139bd5', 'e5682469-845e-5c93-aab0-bd09692f15a7', 'kodr-catalog', 'Владение и заимствование', 'Что делает вызов inspect(&name), если name имеет тип String, а параметр inspect имеет тип &str?', TRUE, 'QUIZ',
     NULL, NULL, NULL, NULL, $json$ [{"id": "a", "text": "Даёт функции общий доступ к строковым данным."}, {"id": "b", "text": "Передаёт функции владение буфером строки."}, {"id": "c", "text": "Выделяет новый буфер для обязательной копии."}, {"id": "d", "text": "Даёт функции право менять буфер строки."}]$json$::jsonb, $json$ ["a"]$json$::jsonb),
    ('350bcc66-2292-5603-882e-38d85741d729', 'e5682469-845e-5c93-aab0-bd09692f15a7', 'kodr-catalog', 'Формат координат', 'Считайте два целых числа x и y от −1000000 до 1000000. Реализуйте Display для Point и с помощью println! выведите координаты в формате «(x, y)».', TRUE, 'PRACTICAL',
     $json$ {"RUST": "use std::fmt;\nuse std::io::{self, Read};\n\nstruct Point {\n    x: i32,\n    y: i32,\n}\n\nimpl fmt::Display for Point {\n    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {\n        // Запишите координаты в f.\n        write!(f, \"\")\n    }\n}\n\nfn main() {\n    let mut input = String::new();\n    io::stdin().read_to_string(&mut input).unwrap();\n    let mut values = input.split_whitespace().map(|n| n.parse::<i32>().unwrap());\n    let point = Point {\n        x: values.next().unwrap(),\n        y: values.next().unwrap(),\n    };\n    println!(\"{}\", point);\n}\n"}$json$::jsonb, $json$ [{"stdin": "7 2\n", "expectedOutput": "(7, 2)"}, {"stdin": "-12 0\n", "expectedOutput": "(-12, 0)"}, {"stdin": "0 -1000000\n", "expectedOutput": "(0, -1000000)"}]$json$::jsonb, 2.0, 128000, NULL, NULL),
    ('dacdeee5-abff-5ae0-b7af-c27bf8baafd1', 'e5682469-845e-5c93-aab0-bd09692f15a7', 'kodr-catalog', 'Форматирование и трейты', 'Какой трейт должен реализовать тип, чтобы его значение можно было вывести с форматом {}?', TRUE, 'QUIZ',
     NULL, NULL, NULL, NULL, $json$ [{"id": "a", "text": "Debug"}, {"id": "b", "text": "Display"}, {"id": "c", "text": "Copy"}, {"id": "d", "text": "Default"}]$json$::jsonb, $json$ ["b"]$json$::jsonb);
